import { sendBatch } from './batch.js';
 import { sendSample } from './sample.js';
 import type { Sender } from './types.js';
 const senders: Record<string, Sender> = { recording: sendBatch, preview: sendSample };
 export function selectSender(plan: string): Sender { return senders[plan] ?? sendSample; }

