import type { Wire } from './types.js';
 export function emitBatchFrame(frame: { partition: string; values: number[] }, wire: Wire) {
   wire.write(JSON.stringify({ kind: 'audio.batch', ...frame }));
 }
 export function emitSampleFrame(frame: { partition: string; value: number }, wire: Wire) {
   wire.write(JSON.stringify({ kind: 'audio.sample', ...frame }));
 }
